class VectorMathError extends Error {
	constructor (message) {
		super(message);
		this.name = 'VectorMathError';
	}
}

class Expression extends Array {
	constructor () {
		if (arguments.length == 1) {
			super();
			this[0] = arguments[0];
		}
		else
			super(...arguments);
	}
	calc () {
		function __calc__ (Exp) {
			let findMxByPriority = a => a.indexOf(a.reduce((a, b) => b instanceof Action && b.priority > a.priority ? b : a, {priority: 0}));
			while (Exp.length > 1) {
				let index = findMxByPriority(Exp);
				if (!Exp[index].unary) Exp.splice(index - 1, 3, Exp[index].use(Exp[index - 1], Exp[index + 1]));
				else Exp.splice(index, 2, Exp[index].use(Exp[index + 1]));
			}
			return Exp[0];
		}

		if (this.length == 0) { return this.defaultValue() } // in vector formule mode it could be zero vector (just for not causing more errors)

		let arr = this.slice()/*.reduce((a, b) => {
			if (a.last == minus)
				if (b == minus) return a.slice(0, -1).concat(plus);
				else if (b == plus) return a.slice(0, -1).concat(minus);
			else if (a.last == plus)
				if (b == minus) return a.slice(0, -1).concat(minus);
				else if (b == plus) return a.slice(0, -1).concat(plus);
			return a.concat(b);
			}, [] ).reduce((a, b) => {
				if (b == minus && (a.last instanceof Action || a.last == undefined))
					return a.concat(unarMinus);
				else if (b == plus && (a.last instanceof Action || a.last == undefined))
					return a;
				return a.concat(b);
			}, [] )*/.map(a => a instanceof Root || a instanceof Variable || a instanceof Expression ? a.calc() : a);
		if (arr.some(a => a instanceof VectorMathError || a instanceof Vector && a.error))
			throw new VectorMathError('Error');

		if (arr.reduce(function (a, b) {
			if (b instanceof Bracket)
				if (b.open) a++;
				else if (!b.open && a > 0) a--;
				else throw new VectorMathError('mathError')
			return a;
		}, 0) != 0)
			throw new VectorMathError(); // checks bracket sequence

		function rFindBracket (arr, index0) { for (let i = index0 - 1; i >= 0; i--) if (arr[i].open) return i }
		let index, index1, res;
		while ( ~(index = arr.findIndex(a => a instanceof Bracket && !a.open)) ) {
			index1 = rFindBracket(arr, index);
			try {
				arr.splice(index1, index - index1 + 1, __calc__( arr.slice(index1 + 1, index) ));
			}
			catch (e) {
				throw e;
			}
		}
		return __calc__(arr);
	}
	includes (obj) {
		return this.some(a => a == obj || (a.includes != undefined ? a.includes(obj) : false));
	}
	static get [Symbol.species] () { return Array }
	defaultValue () {
		return this.def;
	}
}

class Num {
	constructor (value) { this.value = value }
	add (b) { return new Num(this.calc() + b.calc()) }
	sub (b) { return new Num(this.calc() - b.calc()) }
	mul (b) {
		if (b instanceof Vector)
			return b.calc().mul(this.calc());
		return new Num(this.calc() * b.calc())
	}
	div (b) {
		if (b.calc() == 0)
			throw new Error('Нельзя делить на ноль');
		return new Num(this.calc() / b.calc())
	}
	pow (b) { return new Num(Math.pow(this.calc(), b.calc())) }
	calc () { return this.value }
}

class State {
	constructor (parent) {
		this.p = parent;
	}
}

class OrtsState extends State {
	name = 'orts'
	getVx () { return this.p.vx.calc() }
	setVx (value) { this.p.vx = new Expression(...value) }
	getVy () { return this.p.vy.calc() }
	setVy (value) { this.p.vy = new Expression(...value) }
	getAbs () { return this.p.abs.calc() }
	getAngle () {
		if (this.p.vx == 0)
			return Math.PI / 2 * (this.vy > 0 ? 1 : -1);
		return Math.atan2(this.vy, this.vx);
	}
	getFormule () { return new Expression(this.p) }
	init () {

	}
}

let AbsState = {
	getVx () { return this.abs * Math.cos(this.angle) },
	getVy () { return this.abs * Math.sin(this.angle) },
	getAbs () { return this.p.abs.calc() },
	setAbs (value) { this.p.abs = new Expression(...value) },
	getAngle () { return this.p.angle.calc() },
	setAngle (value) { this.p.angle = new Expression(...value) },
	getFormule () { return new Expression(this.p) },
	init () {

	},
	name: 'abs',
}

let FormuleState = {
	get formule () { return this.p.formule },
	set formule (value) {

	},
}

class Vector {
	constructor () {
		this.state = new OrtsState(this);
	}

	get vx () { return this.__state__.getVx() }
	set vx (value) { this.__state.setVx(value) }
	get vy () { return this.__state__.getVy() }
	set vy (value) { this.__state.setVy(value) }
	get abs () { return this.__state__.getAbs() }
	set abs (value) { this.__state.setAbs(value) }
	get angle () { return this.__state__.getAngle() }
	set angle (value) { this.__state.setAngle(value) }
	get sx () { return this.__state__.getSx() }
	set sx (value) { this.__state__.setSx(value) }
	get sy () { return this.__state__.getSy() }
	set sy (value) { this.__state__.setSy(value) }

	set state (value) {
		this.__state__ = value;
		this.__state__.init();
	}
	get state () {
		return this.__state__.name;
	}
}

let variablesCache = new Map();

class Variable {
	constructor () {
		this.subscribers = new Set();
		this.Exp = []; // just bugfix, don't delete
		this.value = arguments;
		variablesCache.set(this, this.value.calc());
	}
	calc () {
		return variablesCache.get(this);
	}
	get value () {
		return this.Exp;
	}
	set value (value) {
		for (let item of this.value)
			if (item instanceof Variable)
				item.removeSubscriber(this);
		this.Exp = new Expression(...value);
		for (let item of this.value)
			if (item instanceof Variable)
				item.addSubscriber(this);
	}
	change () {
		this.value = arguments;
		this.recalc();
		this.notifySubscribers();
	}
	addSubscriber (variable) {
		this.subscribers.add(variable);
	}
	removeSubscriber (variable) {
		this.subscribers.delete(variable);
	}
	notifySubscribers () {
		for (let item of this.subscribers)
			item.recalc();
	}
	recalc0 () {
		try {
			variablesCache.set(this, this.value.calc());
		}
		catch (e) {
			variablesCache.set(this, e);
			// throw e;
		}
	}
	recalc () {
		this.recalc0()
	}
}

class Action {
	constructor (priority, unary=false) {
		this.priority = priority;
		this.unary = unary;
	}
	use (a, b, calc) {
		if (!this.checkClass(a, b))
			throw new Error('Invalid types');
		try { return calc(a, b) }
		catch (e) { throw e }
	}
	checkClass (a, b) {
		return (b == undefined) || (a.constructor === b.constructor);
	}
}

class Plus extends Action {
	constructor () { super(3) }
	use (a, b) { return super.use( a, b, (a, b) => a.add(b) ) }
}

class Minus extends Action {
	constructor () { super(3) }
	use (a, b) { return super.use( a, b, (a, b) => a.sub(b) ) }
}

class Mul extends Action {
	constructor () { super(4) }
	use (a, b) { return super.use( a, b, (a, b) => a.mul(b) ) }
	checkClass (a, b) { return !(a.calc() instanceof Vector && b.calc() instanceof Vector) }
}

class Div extends Action {
	constructor () { super(4) }
	use (a, b) { return super.use( a, b, (a, b) => a.div(b) ) }
	checkClass (a, b) { return super.checkClass(a, b) && a instanceof Num }
}

class Pow extends Action {
	constructor () { super(5) }
	use (a, b) { return super.use( a, b, (a, b) => a.pow(b) ) }
	checkClass (a, b) { return super.checkClass(a, b) && a instanceof Num }
}

class Root {
	constructor (content) { this.content = content }
	calc () {
		return this.content.calc();
	}
	includes (obj) { return this.content.includes(obj) }
}

class Bracket { constructor (open) { this.open = open } }

class UnaryMinus extends Action {
	constructor () { super(6, true) }
	use (a) { return super.use( a, a => a.mul(-1) ) }
	checkClass (a) { return true; }
}

class UnaryPlus extends Action {
	constructor () { super(6, true) }
	use (a) { return super.use( a, a => a ) }
	checkClass (a) { return true; }
}

class Sin extends Action {
	constructor () { super(7, true) }
	use (a) { return super.use( a, a => Math.sin(a) ) }
}

class Cos extends Action {
	constructor () { super(7, true) }
	use (a) { return super.use( a, a => Math.cos(a) ) }
}

class Tan extends Action {
	constructor () { super(7, true) }
	use (a) { return super.use( a, a => Math.tan(a) ) }
}

class ScMul extends Action {
	constructor () { super(2) }
	use (a, b) { return super.use( a, b, (a, b) => a.vx * b.vx + a.vy * b.vy ) }
	checkClass (a, b) { return a instanceof Vector && b instanceof Vector }
}